<script setup lang="ts">import{apiErrorMessage}from'~/utils/api-error';useHead({title:'Mot de passe oublié'});const email=ref('');const pending=ref(false);const message=ref('');const errorMessage=ref('');async function submit(){pending.value=true;message.value='';errorMessage.value='';try{const response=await $fetch<{ok:true;data:{message:string}}>('/api/auth/password/forgot',{method:'POST',body:{email:email.value}});message.value=response.data.message}catch(error){errorMessage.value=apiErrorMessage(error,'Impossible de traiter la demande.')}finally{pending.value=false}}</script>
<template><section class="section"><div class="container auth-narrow"><form class="card card-pad" @submit.prevent="submit"><p class="eyebrow">Accès IFICS</p><h1>Réinitialiser le mot de passe</h1><p class="muted">La réponse reste identique même si l’adresse n’est pas connue, afin de protéger les comptes.</p><div v-if="message" class="alert alert-success" role="status">{{message}}</div><div v-if="errorMessage" class="alert alert-error" role="alert">{{errorMessage}}</div><div class="field"><label for="forgot-email">E-mail</label><input id="forgot-email" v-model="email" class="input" type="email" required></div><button class="btn btn-primary" :disabled="pending" type="submit">{{pending?'Envoi…':'Envoyer les instructions'}}</button></form></div></section></template>
<style scoped>.auth-narrow{max-width:560px}.card{display:flex;flex-direction:column;gap:16px}.card h1,.card p{margin:0}</style>
